{
  "name": "ko-ai",
  "version": "0.2.2",
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "author": "Jason Miller (https://jasonformat.com)",
  "license": "MIT",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./agent": {
      "types": "./dist/agent.d.ts",
      "import": "./dist/agent.js"
    },
    "./agent-tools": {
      "types": "./dist/agent-tools.d.ts",
      "import": "./dist/agent-tools.js"
    },
    "./agent-signals": {
      "types": "./dist/agent-signals.d.ts",
      "import": "./dist/agent-signals.js"
    }
  },
  "files": [
    "src",
    "dist"
  ],
  "scripts": {
    "build": "tsup --clean",
    "build-demo": "pnpm --filter demo build",
    "dev": "tsup --watch",
    "test": "node --test **/*.test.ts",
    "test:watch": "node --test --watch **/*.test.ts",
    "test:record": "KOAI_TEST_MODE=record node --test **/*.test.ts",
    "test:validate": "node test/validate-fixtures.ts",
    "pretest": "pnpm run build",
    "changeset": "changeset",
    "version-packages": "changeset version",
    "prepublishOnly": "pnpm run build",
    "release": "changeset publish"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/developit/ko-ai.git"
  },
  "publishConfig": {
    "access": "public",
    "provenance": true
  },
  "peerDependencies": {
    "@preact/signals-core": ">=1.14.0"
  },
  "peerDependenciesMeta": {
    "@preact/signals-core": {
      "optional": true
    }
  },
  "devDependencies": {
    "@changesets/cli": "^2.29.8",
    "@preact/signals-core": "^1.14.0",
    "@types/node": "^24.10.1",
    "mock-openai-api": "^1.0.3",
    "nock": "^14.0.10",
    "tsup": "^8.0.0",
    "typescript": "^5.3.0"
  }
}

import { defineConfig } from 'vite'
import preact from '@preact/preset-vite'
import { nodePolyfills } from 'vite-plugin-node-polyfills'
import tailwindcss from '@tailwindcss/vite'

// https://vite.dev/config/
export default defineConfig({
  plugins: [
    preact(),
    tailwindcss(),
    nodePolyfills({
      // Enable polyfills for zlib and other node modules
      include: ['zlib', 'stream', 'buffer', 'util'],
      globals: {
        Buffer: true,
        global: true,
        process: true
      }
    })
  ],
  resolve: {
    alias: {
      // Use browser-specific just-bash build
      'just-bash': 'just-bash/browser',
      // Stub node:module import that just-bash tries to use
      'node:module': new URL('./src/stubs/module.js', import.meta.url).pathname
    }
  },
  optimizeDeps: {
    exclude: ['just-bash']
  }
})

