import { resolve } from 'path';
import fs from 'fs/promises';
import { defineConfig } from 'vite';
import preact from '@preact/preset-vite';
import icons from 'unplugin-icons/vite';
import mkcert from 'vite-plugin-mkcert';
// import basicSsl from '@vitejs/plugin-basic-ssl';
// import iconsResolver from 'unplugin-icons/resolver';
// import autoImport from 'unplugin-auto-import/vite';

// https://vitejs.dev/config/
export default defineConfig({
	// server: {
	// 	host: '0.0.0.0',
	// 	port: 8080,
	// },
	server: {
		host: '0.0.0.0',
		https: true,
	},
	build: {
		modulePreload: {
			polyfill: false,
		},
		assetsInlineLimit: 512,
		// minify: 'terser',
	},
	// experimental: {
	// 	renderBuiltUrl(filename, type) {
	// 	}
	// },
	// resolve: {
	// 	alias: {
	// 		'iconify-icon': resolve(__dirname, 'src/lib/icon.js'),
	// 	},
	// },
	// esbuild: {
	// 	keepNames: false,
	// 	treeShaking: true,
	// 	mangleCache: {},
	// 	mangleProps:
	// 		/^(shouldComponent.*|componentWill.*|componentDid.*|_(set|get|update|walk|sig|response).*)$/,
	// },

	// worker: {
	// 	format: 'iife',
	// 	rollupOptions: {
	// 		output: {
	// 			entryFileNames(chunk) {
	// 				if (/\/sw(\/index)?\.[jt]sx?$/.test(chunk.facadeModuleId)) {
	// 					return 'sw.js';
	// 				}
	// 				return chunk.name;
	// 			},
	// 		},
	// 	},
	// },

	plugins: [
		{
			name: 'service-worker',
			enforce: 'pre',
			// in development, a middlware injects empty VERSION and ASSETS globals
			configureServer(server) {
				server.middlewares.use((req, res, next) => {
					if (/\?swdev$/.test(req.url + '')) {
						res.setHeader('Service-Worker-Allowed', '/');
						let prefix = 'var VERSION="dev",ASSETS=[];\n';
						let { write, end } = res;
						res.write = function () {
							if (prefix) write.call(this, prefix);
							prefix = '';
							return write.apply(this, arguments);
						};
						res.end = function () {
							if (prefix) write.call(this, prefix);
							prefix = '';
							return end.apply(this, arguments);
						};
					}
					next();
				});
			},
			// in development, load SW using `?url` but tag so the middlware can inject into it
			async resolveId(id, importer) {
				if (this.meta.watchMode && /\?sw$/.test(id)) {
					id = id.replace(/\?.+$/, '');
					return this.resolve(id + '?url&swdev', importer);
				}
			},
			async load(id) {
				if (this.meta.watchMode || !/\?sw$/.test(id)) return;
				id = id.replace(/\?.+$/, '');
				const file = this.emitFile({
					fileName: 'sw.js',
					type: 'asset',
					source: await fs.readFile(id, 'utf-8'),
				});
				return `export default import.meta.ROLLUP_FILE_URL_${file}`;
			},
			generateBundle(_, bundle) {
				const manifest = [];
				for (const fileName in bundle) {
					if (/\.map$/.test(fileName) || fileName === 'sw.js') continue;
					// @todo - squash index.html?
					manifest.push('/' + fileName);
					// const chunk = bundle[fileName];
					// if (chunk.type === 'chunk') manifest.push(fileName);
					// else if (chunk.fileName) manifest.push(fileName);
				}
				console.log('SW Assets: ', manifest);
				function hash(s) {
					for (var i = 0, h = 0; i < s.length; i++) h = (Math.imul(31, h) + s.charCodeAt(i)) | 0;
					return h;
				}
				const sw = bundle['sw.js'];
				if (sw && sw.type === 'asset') {
					const assets = JSON.stringify(manifest);
					const version = hash(assets).toString(36);
					sw.source = `var VERSION="${version}",ASSETS=${assets};\n${sw.source}`;
				}
			},
		},
		{
			name: 'iconify',
			transform(code, id) {
				if (!/\.[tj]sx$/i.test(id) || !/[<'"]iconify-icon['" ]/.test(code)) return;
				const imports = new Set();
				code = code.replace(
					// /<iconify-icon(?:\s+[^>{}]+?)?\s+icon=(['"])([a-zA-Z0-9_-]+):([a-zA-Z0-9_-]+)\1(?:\s+[^>{}]+?)?\s*\/>/g,
					/(['"])iconify-icon\1,\s*\{\s*[^}]*?\s*icon:\s*(['"])([a-zA-Z0-9_-]+):([a-zA-Z0-9_-]+)\2/g,
					(str, _, _2, collection, icon) => {
						imports.add(`~icons/${collection}/${icon}`);
						return str;
					}
				);
				code += `\n${[...imports].map((i) => `import "${i}";`).join('')}`;
				return { code, map: null };
			},
		},
		// autoImport({
		// 	resolvers: [
		// 		iconsResolver({
		// 			// prefix: 'Icon',
		// 			prefix: 'icon',
		// 			enabledCollections: ['mdi', 'majesticons'],
		// 			extension: 'jsx',
		// 		}),
		// 	],
		// }),
		icons({
			autoInstall: true,
			// compiler: 'jsx',
			jsx: 'preact',
			compiler: {
				async compiler(svg, collection, icon, options) {
					const [, viewBox, body] =
						svg.match(/<svg(?: [^>]*?)? viewBox="([^"]+)"(?: [^>]*?)?>([\s\S]*)<\/svg>/i) || [];
					const [, , width, height] = viewBox.split(/\s+/);
					const name = JSON.stringify(`${collection}:${icon}`);
					return `
						import { addIcon } from '${resolve(__dirname, 'src/lib/icon.js')}';
						addIcon(${name}, { body: ${JSON.stringify(body)}, width: ${width}, height: ${height} });
					`;
					// return `export default props => <iconify-icon icon=${name} {...props} />;`;
				},
				extension: '.jsx',
			},
			// compiler: 'web-components',
			// webComponents: {
			// 	autoDefine: true,
			// 	iconPrefix: 'icon',
			// },
		}),
		preact(),
		mkcert(),
	],
});

